import { isEmpty } from 'lodash-es';
import { useCallback } from 'react';
import {
  useWebAuthnCertificationOptionsMutation,
  useWebAuthnCertificationMutation,
} from '~/entities/biometric/api/use-webauthn-certification-mutation';
import { useAuthnNativeCertification } from '~/entities/biometric/lib/use-authn-native-certification';
import { UserResponse } from '~/entities/pin/api/dtos/types';
import { getUserRes } from '~/entities/user/api/use-get-cstmr-query';
import { PinInteractionMode } from '~/shared/api/dtos/enums';
import i18n from '~/shared/i18n/i18n';

type AuthenticationCallbacks = {
  success: () => void;
  error: (error: string) => void;
};

export const useAuthentication = () => {
  const { mutateAsync: webAuthnCertificationOptions } = useWebAuthnCertificationOptionsMutation({
    throwOnError: false,
  });
  const { mutateAsync: webAuthnCertification } = useWebAuthnCertificationMutation({
    throwOnError: false,
  });
  const { certification: nativeCertification } = useAuthnNativeCertification();

  const authenticate = useCallback(
    async ({ success, error }: AuthenticationCallbacks, type: PinInteractionMode) => {
      try {
        // 1. 사용자 정보 가져오기
        const userRes = getUserRes() as UserResponse;
        const cstmrNo = userRes.tbCstmrMastr?.cstmrNo;

        if (!cstmrNo) {
          error('사용자 정보를 찾을 수 없습니다.');
          return;
        }

        // 2. WebAuthn certification options 요청

        const certificationOptions = await webAuthnCertificationOptions({
          username: cstmrNo,
        });

        if (isEmpty(certificationOptions.publicKey.allowCredentials)) {
          if (type === PinInteractionMode.로그인) {
            error('등록된 패스키가 없습니다. 핀번호로 로그인 해주세요.');
          } else if (type === PinInteractionMode.인증 || type === PinInteractionMode.인증_바텀시트) {
            error('등록된 패스키가 없습니다. 설정에서 패스키를 등록해주세요.');
          }
          return;
        }

        // 3. 네이티브에서 생체인증 수행
        const certificationCredential = await nativeCertification({
          webAuthnOptions: certificationOptions.publicKey,
          username: cstmrNo,
        });

        certificationCredential.payload.type = type;

        // 4. 서버에 인증 요청
        await webAuthnCertification(certificationCredential.payload);

        // 5. 성공 콜백 호출
        success();
      } catch (e: any) {
        error(i18n.t('pin:errorBiometricAuth'));
      }
    },
    [webAuthnCertificationOptions, nativeCertification, webAuthnCertification],
  );

  return {
    authenticate,
  };
};
