import { useMutation } from '@tanstack/react-query';
import axios from 'axios';
import { useStore } from '~/app/store/store';
import { WebAuthnFinishReq, WebAuthnFirstStepReq, WebAuthnFirstStepRes } from '~/entities/biometric/model/types';
import { LoginParams } from '~/entities/pin/api/dtos/types';
import { CBDCAxiosError } from '~/shared/@types/error';
import { MutationOptions } from '~/shared/@types/query';
import { API_URLS } from '~/shared/api/api-urls';
import { PinInteractionMode } from '~/shared/api/dtos/enums';
import { resultify } from '~/shared/lib/utils/resultify';

// 생체인증 요청 옵션
export const webAuthnCertificationOptions = ({ username }: WebAuthnFirstStepReq) => {
  return resultify(axios.post<WebAuthnFirstStepRes>(API_URLS.authLbdyUse(''), { username }));
};

// 생체인증 요청 완료 (서버에서 받은 인증 결과로 최종 인증)
export const webAuthnCertification = ({ username, credential, type }: WebAuthnFinishReq) => {
  let url = 'passkey';
  if (type === PinInteractionMode.로그인) {
    url = 'finish';
  }
  return resultify(
    axios.post<LoginParams>(API_URLS.authLbdyUse(url), {
      username,
      credential,
    }),
  );
};

export const useWebAuthnCertificationOptionsMutation = (
  options?: MutationOptions<WebAuthnFirstStepReq, CBDCAxiosError, WebAuthnFirstStepRes>,
) => {
  const mutation = useMutation<WebAuthnFirstStepRes, CBDCAxiosError, WebAuthnFirstStepReq>({
    ...options,
    mutationFn: webAuthnCertificationOptions,
  });
  return {
    ...mutation,
  };
};

export const useWebAuthnCertificationMutation = (
  options?: MutationOptions<WebAuthnFinishReq, CBDCAxiosError, LoginParams>,
) => {
  const setIncorrectPinCount = useStore.getState().pinSlice.setIncorrectPinCount;
  const mutation = useMutation<LoginParams, CBDCAxiosError, WebAuthnFinishReq>({
    ...options,
    mutationFn: webAuthnCertification,
    onSuccess: (data) => {
      setIncorrectPinCount(0);

      const { setJwt } = useStore.getState().authSlice;
      setJwt(data.accessToken);
    },
  });
  return {
    ...mutation,
  };
};
